#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin. Created: 2026-09-07
# /ork:page-serve status: list every served page with a live check per row.
#
# For each state file: is the server pid alive, is the alias registered, does the
# URL answer 200 through the proxy. All three are measured now, not read from the
# state file, so a row that says "up" is a row that is up.
#
# Exit codes: 0 always (this is a report). Output is one line per page plus a
# summary; machine-readable with --json.

set -euo pipefail

PROJECT_DIR="${CLAUDE_PROJECT_DIR:-$(pwd)}"
STATE_DIR="${PROJECT_DIR}/.claude/state/page-serve"
JSON=0
[[ "${1:-}" == "--json" ]] && JSON=1

if [[ ! -d "$STATE_DIR" ]]; then
  [[ "$JSON" == "1" ]] && printf '[]\n' || printf 'page-serve: nothing served\n'
  exit 0
fi

routes="$(portless list 2>&1 || true)"  # silent: gating-relaxed (a missing proxy reads as "no routes", reported per row below)

rows=()
for f in "${STATE_DIR}"/*.json; do
  [[ -e "$f" ]] || continue
  name="$(basename "$f" .json)"
  pid="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1])).get("pid",0))' "$f")"
  url="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1])).get("url",""))' "$f")"
  port="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1])).get("port",""))' "$f")"

  # silent: gating-relaxed (liveness probe)
  if [[ -n "$pid" && "$pid" != "0" ]] && kill -0 "$pid" 2>/dev/null; then alive="up"; else alive="dead"; fi
  case "$routes" in *"${name}.localhost"*) route="registered" ;; *) route="missing" ;; esac
  code="$(curl -sSk -o /dev/null -m 5 -w '%{http_code}' "$url" 2>&1)"; crc=$?
  [[ "$crc" == "0" ]] || code="000"

  if [[ "$JSON" == "1" ]]; then
    rows+=("$(python3 -c 'import json,sys; print(json.dumps(dict(name=sys.argv[1],url=sys.argv[2],port=int(sys.argv[3] or 0),pid=int(sys.argv[4] or 0),server=sys.argv[5],route=sys.argv[6],http=sys.argv[7])))' "$name" "$url" "$port" "$pid" "$alive" "$route" "$code")")
  else
    printf '%-24s %-6s %-11s http=%s  %s\n' "$name" "$alive" "$route" "$code" "$url"
  fi
done

if [[ "$JSON" == "1" ]]; then
  printf '['; local_sep=""; for r in "${rows[@]:-}"; do [[ -n "$r" ]] || continue; printf '%s%s' "$local_sep" "$r"; local_sep=","; done; printf ']\n'
else
  [[ "${#rows[@]}" -gt 0 || -n "$(ls -A "$STATE_DIR" 2>/dev/null)" ]] || printf 'page-serve: nothing served\n'  # silent: gating-relaxed (empty dir is the expected case)
fi
